dom_assertions.publish_btn_body_excerpt:
data-testid="publish-now"
            data-export-state={exportState}
            disabled={exportState === "exporting"}
            onClick={publishNow}
          >
            {}
            {exportState === "exporting"
              ? "Exporting…"
              : exportState === "done"
                ? "Exported ✓"
                : exportState === "error"
                  ? "Retry export"
